CREATE TABLE `career_opportunities` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`opportunity_reference` varchar(40) NOT NULL,`title` varchar(255) NOT NULL,`organisation` varchar(255) NOT NULL,`location` varchar(255) DEFAULT NULL,`province_id` bigint unsigned DEFAULT NULL,`profession_id` bigint unsigned DEFAULT NULL,`employment_type` varchar(40) NOT NULL,`work_arrangement` varchar(40) DEFAULT NULL,`summary` varchar(500) NOT NULL,`description` text NOT NULL,`requirements` text NOT NULL,`application_instructions` text DEFAULT NULL,`external_url` varchar(1000) DEFAULT NULL,`closing_date` date NOT NULL,`status` varchar(30) NOT NULL DEFAULT 'draft',`published_at` timestamp NULL DEFAULT NULL,`created_by` bigint unsigned NOT NULL,`updated_by` bigint unsigned NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `career_opportunities_reference_unique`(`opportunity_reference`),KEY `career_opportunities_public_index`(`status`,`closing_date`,`published_at`),KEY `career_opportunities_province_index`(`province_id`,`status`),KEY `career_opportunities_profession_index`(`profession_id`,`status`),CONSTRAINT `career_opportunities_province_foreign` FOREIGN KEY(`province_id`) REFERENCES `provinces`(`id`) ON DELETE SET NULL,CONSTRAINT `career_opportunities_profession_foreign` FOREIGN KEY(`profession_id`) REFERENCES `professions`(`id`) ON DELETE SET NULL,CONSTRAINT `career_opportunities_creator_foreign` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `career_opportunities_updater_foreign` FOREIGN KEY(`updated_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `career_applications` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`application_reference` varchar(40) NOT NULL,`career_opportunity_id` bigint unsigned NOT NULL,`applicant_user_id` bigint unsigned NOT NULL,`cover_letter` text DEFAULT NULL,`experience_summary` text DEFAULT NULL,`status` varchar(30) NOT NULL DEFAULT 'draft',`submitted_at` timestamp NULL DEFAULT NULL,`reviewed_by` bigint unsigned DEFAULT NULL,`review_started_at` timestamp NULL DEFAULT NULL,`decided_at` timestamp NULL DEFAULT NULL,`decision_reason` varchar(1000) DEFAULT NULL,`private_reviewer_note` varchar(2000) DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `career_applications_reference_unique`(`application_reference`),UNIQUE KEY `career_applications_applicant_unique`(`career_opportunity_id`,`applicant_user_id`),KEY `career_applications_applicant_status_index`(`applicant_user_id`,`status`),KEY `career_applications_status_index`(`status`,`submitted_at`),CONSTRAINT `career_applications_opportunity_foreign` FOREIGN KEY(`career_opportunity_id`) REFERENCES `career_opportunities`(`id`) ON DELETE RESTRICT,CONSTRAINT `career_applications_applicant_foreign` FOREIGN KEY(`applicant_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `career_applications_reviewer_foreign` FOREIGN KEY(`reviewed_by`) REFERENCES `users`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `career_application_events` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`career_application_id` bigint unsigned NOT NULL,`actor_user_id` bigint unsigned DEFAULT NULL,`previous_status` varchar(30) DEFAULT NULL,`new_status` varchar(30) NOT NULL,`action` varchar(80) NOT NULL,`note` varchar(1000) DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),KEY `career_application_events_timeline_index`(`career_application_id`,`created_at`),CONSTRAINT `career_application_events_application_foreign` FOREIGN KEY(`career_application_id`) REFERENCES `career_applications`(`id`) ON DELETE RESTRICT,CONSTRAINT `career_application_events_actor_foreign` FOREIGN KEY(`actor_user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `bursary_opportunities` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`opportunity_reference` varchar(40) NOT NULL,`title` varchar(255) NOT NULL,`provider` varchar(255) NOT NULL,`field_of_study` varchar(255) NOT NULL,`description` text NOT NULL,`eligibility_criteria` text NOT NULL,`benefits` text NOT NULL,`study_level` varchar(100) NOT NULL,`opening_date` date NOT NULL,`closing_date` date NOT NULL,`status` varchar(30) NOT NULL DEFAULT 'draft',`published_at` timestamp NULL DEFAULT NULL,`created_by` bigint unsigned NOT NULL,`updated_by` bigint unsigned NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `bursary_opportunities_reference_unique`(`opportunity_reference`),KEY `bursary_opportunities_public_index`(`status`,`opening_date`,`closing_date`),KEY `bursary_opportunities_field_index`(`field_of_study`,`status`),KEY `bursary_opportunities_level_index`(`study_level`,`status`),CONSTRAINT `bursary_opportunities_creator_foreign` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `bursary_opportunities_updater_foreign` FOREIGN KEY(`updated_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `bursary_opportunities_dates_check` CHECK (`closing_date` >= `opening_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `bursary_applications` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`application_reference` varchar(40) NOT NULL,`bursary_opportunity_id` bigint unsigned NOT NULL,`applicant_user_id` bigint unsigned NOT NULL,`institution` varchar(255) DEFAULT NULL,`qualification` varchar(255) DEFAULT NULL,`study_level` varchar(100) DEFAULT NULL,`motivation` text DEFAULT NULL,`declaration_confirmed` tinyint(1) NOT NULL DEFAULT 0,`status` varchar(30) NOT NULL DEFAULT 'draft',`submitted_at` timestamp NULL DEFAULT NULL,`reviewed_by` bigint unsigned DEFAULT NULL,`review_started_at` timestamp NULL DEFAULT NULL,`decided_at` timestamp NULL DEFAULT NULL,`decision_reason` varchar(1000) DEFAULT NULL,`private_reviewer_note` varchar(2000) DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `bursary_applications_reference_unique`(`application_reference`),UNIQUE KEY `bursary_applications_applicant_unique`(`bursary_opportunity_id`,`applicant_user_id`),KEY `bursary_applications_applicant_status_index`(`applicant_user_id`,`status`),KEY `bursary_applications_status_index`(`status`,`submitted_at`),CONSTRAINT `bursary_applications_opportunity_foreign` FOREIGN KEY(`bursary_opportunity_id`) REFERENCES `bursary_opportunities`(`id`) ON DELETE RESTRICT,CONSTRAINT `bursary_applications_applicant_foreign` FOREIGN KEY(`applicant_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `bursary_applications_reviewer_foreign` FOREIGN KEY(`reviewed_by`) REFERENCES `users`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `bursary_application_events` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`bursary_application_id` bigint unsigned NOT NULL,`actor_user_id` bigint unsigned DEFAULT NULL,`previous_status` varchar(30) DEFAULT NULL,`new_status` varchar(30) NOT NULL,`action` varchar(80) NOT NULL,`note` varchar(1000) DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),KEY `bursary_application_events_timeline_index`(`bursary_application_id`,`created_at`),CONSTRAINT `bursary_application_events_application_foreign` FOREIGN KEY(`bursary_application_id`) REFERENCES `bursary_applications`(`id`) ON DELETE RESTRICT,CONSTRAINT `bursary_application_events_actor_foreign` FOREIGN KEY(`actor_user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
